func (s *Store) Claim(ctx context.Context, id string, prev int, provider string, lease time.Duration, extra map[string]any) (bool, error) {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return false, err
	}
	defer tx.Rollback()
	now := time.Now().UTC()
	var from string
	err = tx.QueryRowContext(ctx, `SELECT status FROM notifications WHERE id=? AND attempts=? FOR UPDATE`, id, prev).Scan(&from)
	if err == sql.ErrNoRows {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	ok := false
	for _, c := range claimable {
		if from == c {
			ok = true
		}
	}
	if !ok {
		return false, nil
	}
	if _, err := tx.ExecContext(ctx, `UPDATE notifications SET status=?, attempts=?, lease_until=?, updated_at=? WHERE id=?`, StatusSending, prev+1, now.Add(lease), now, id); err != nil {
		return false, err
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO delivery_attempts (notification_id, attempt, provider, started_at, outcome) VALUES (?,?,?,?,?)`,
		id, prev+1, provider, now, "IN_FLIGHT"); err != nil {
		return false, err
	}
	data := map[string]any{"attempt": prev + 1, "provider": provider, "lease_until": now.Add(lease)}
	for k, v := range extra {
		data[k] = v
	}
	if err := AddEvent(ctx, tx, id, "claimed", from, StatusSending, data); err != nil {
		return false, err
	}
	return true, tx.Commit()
}

