	var out []*Consumer
	for _, ch := range Channels {
		kc, err := ConsumerClient(brokers, GroupFor(groupBase, ch), []string{topics.For(ch)}, session, onAssigned)
		if err != nil {
			CloseAll(out)
			return nil, err
		}
