func (s *Server) createOnce(ctx context.Context, c store.Client, req Request, key string) (created, error) {
	params, _ := json.Marshal(req.Params)
	now := time.Now().UTC()
	n := &store.Notification{ID: ids.New("ntf_"), ClientID: c.ID, Channel: req.Channel, Recipient: req.Recipient, Template: req.Template,
		Params: params, Status: store.StatusQueued, CreatedAt: now, UpdatedAt: now}
	body, _ := json.Marshal(n)
	hash := Fingerprint(req)

	tx, err := s.Store.DB.BeginTx(ctx, nil)
	if err != nil {
		return created{}, err
	}
	defer tx.Rollback()
	if key != "" {
		// No SELECT first: two concurrent requests would both see "no
		// row" and both insert a notification. The primary key on
		// (client_id, idem_key) lets exactly one INSERT win; the other
		// waits for it to commit and then gets a duplicate-key error.
		err := store.InsertIdem(ctx, tx, store.IdemRecord{ClientID: c.ID, Key: key, RequestHash: hash, NotificationID: n.ID, StatusCode: 202, Response: body, CreatedAt: now})
		if store.IsDuplicateKey(err) {
			_ = tx.Rollback()
			prev, err := s.Store.Idem(ctx, c.ID, key)
			if err != nil {
				return created{}, err
			}
			if prev.RequestHash != hash {
				return created{id: prev.NotificationID}, errKeyReuse
			}
			return created{code: prev.StatusCode, body: prev.Response, id: prev.NotificationID, replayed: true}, nil
		}
		if err != nil {
			return created{}, err
		}
	}
	if err := store.InsertNotification(ctx, tx, n); err != nil {
		return created{}, err
	}
	if err := store.AddEvent(ctx, tx, n.ID, "accepted", "", store.StatusQueued, map[string]any{"request": req, "idempotency_key": key, "request_hash": hash}); err != nil {
		return created{}, err
	}
	if err := s.afterInsert(ctx, tx, n); err != nil {
		return created{}, err
	}
	return created{code: 202, body: body, id: n.ID}, tx.Commit()
}

func (p Policy) Next(attempt int, retryAfter time.Duration) (time.Duration, Calc) {
	ceil := p.Ceiling(attempt)
	c := Calc{Attempt: attempt, BaseMS: ms(p.Base), CapMS: ms(p.Cap), CeilingMS: ms(ceil), RetryAfterMS: ms(retryAfter)}
	var d time.Duration
	if config.Sabotaged(config.NoJitter) {
		// @learn:no-jitter
		c.Jitter = "none"
		d = ceil // everyone who failed together comes back together
		// @learn:end no-jitter
	} else {
		r := rand.Float64
		if p.Rand != nil {
			r = p.Rand
		}
		c.Jitter = "full"
		c.Rand = r()
		d = time.Duration(c.Rand * float64(ceil))
	}
	d += retryAfter
	c.DelayMS = ms(d)
	return d, c
}

func (b *Bucket) Reserve() (wait time.Duration, left float64) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill(b.now())
	b.tokens--
	if b.tokens >= 0 {
		return 0, b.tokens
	}
	return time.Duration(-b.tokens / b.Rate * float64(time.Second)), b.tokens
}

// Wait blocks until the caller may send. If ctx ends first, the token
// is given back.
func (b *Bucket) Wait(ctx context.Context) (waited time.Duration, left float64, err error) {
	// @learn:ratelimit-sabotage
	if b == nil || config.Sabotaged(config.NoRateLimit) {
		return 0, 0, nil // no bucket: every request goes straight out
	}
	// @learn:end ratelimit-sabotage
	wait, left := b.Reserve()
	if wait <= 0 {
		return 0, left, nil
	}
	if err := b.sleep(ctx, wait); err != nil {
		b.Refund()
		return 0, left, err
	}
	return wait, left, nil
}

